public static class PhoenixBuilderChecks
{
    private static readonly ILogger Log=LogFactory.GetLogger(typeof(PhoenixBuilderChecks));
    private sealed class Maximum:Random{public override int Next(int max)=>Math.Max(0,max-1);}
    private sealed record Saved(uint Owner,uint Target,MartialCharge State,int Mana256,uint Pending,int PendingMana,Point3D Origin);
    private static string Manifest=>Path.Join(Core.BaseDirectory,"phoenix-builder-fixtures.json");
    private static bool Creating;
    private static void Rates(){var mp=Mobile.ManaRegenRateHandler;Mobile.ManaRegenRateHandler=p=>Creating || p.Name=="PhoenixBuilderFixture"?TimeSpan.FromHours(1):mp?.Invoke(p)??Mobile.DefaultManaRate;}
    [CallPriority(int.MaxValue)]public static void Initialize()=>Rates();
    public static void Configure(){Rates();Register("phoenix-builder-check",Check);Register("phoenix-builder-reload-check",Reload);Register("phoenix-builder-input-check",Input);}
    private static void Register(string name,Action action)=>ConsoleInputHandler.RegisterCommand(name,"Learned single-contact Phoenix A1 builder/payment/charges",_=>Core.LoopContext.Post(()=>{try{if(name.EndsWith("input-check")){action();}else{Controlled(action);}Log.Information("{Name}: passed",name);}catch(Exception e){Log.Error(e,"{Name}: failed",name);}}));
    private static void Require(bool ok,string why){if(!ok){throw new InvalidOperationException(why);}}
    private static void Controlled(Action action){var hit=TigerStrikes.HitRoll;var element=TigerStrikes.ElementRoll;var physical=TigerStrikes.PhysicalRoll;var effects=TigerStrikes.Effects;var block=SourceBlocking.BlockRoll;try{TigerStrikes.HitRoll=()=>0;TigerStrikes.ElementRoll=()=>0;TigerStrikes.PhysicalRoll=_=>0;TigerStrikes.Effects=new Maximum();SourceBlocking.BlockRoll=_=>99;action();}finally{TigerStrikes.HitRoll=hit;TigerStrikes.ElementRoll=element;TigerStrikes.PhysicalRoll=physical;TigerStrikes.Effects=effects;SourceBlocking.BlockRoll=block;}}
    private static SkillValues Values(int rank)=>new(SkillMechanics.For(CombatAbility.PhoenixStrike),_=>rank,_=>0,99);
    private static PlayerMobile Fresh(){Creating=true;try{var p=BladeBodyChecks.Fresh(6800,10,3050);p.Name="PhoenixBuilderFixture";var dagger=new Dagger();ClassGear.Profiles.Convert(dagger,99,GearRarity.Normal,new Random(173));p.AddToBackpack(dagger);Require(p.EquipItem(dagger),"Dagger");ClassGear.Refresh(p);return p;}finally{Creating=false;}}
    private static BaseCreature Target(PlayerMobile p){var t=new CobraPassiveTarget{Name="PhoenixBuilderTarget",Frozen=true,CantWalk=true,NoKillAwards=true};t.MoveToWorld(new(p.X+1,p.Y,p.Z),p.Map);t.AIObject?.AITimer.Stop();t.SetHits(50000);t.Hits=t.HitsMax;foreach(var type in new[]{ResistanceType.Physical,ResistanceType.Fire,ResistanceType.Cold,ResistanceType.Energy,ResistanceType.Poison}){t.SetResistance(type,0);}return t;}
    private static MartialCharge State(PlayerMobile p)=>AssassinCharges.State(p,CombatAbility.PhoenixStrike);
    private static void Hold(PlayerMobile p,MartialCharge state)=>AssassinCharges.Restore(AssassinCharges.Snapshot().Where(x=>x.Owner!=p.Serial.Value || x.Ability!=CombatAbility.PhoenixStrike).Append(state).ToArray());
    private static void Ready(PlayerMobile p){ClassCombat.Stop(p);var s=ClassCombat.For(p);s.NextAction=s.RecoveryUntil=Core.TickCount;p.Frozen=p.Paralyzed=false;}
    private static void ClearRelease(PlayerMobile p){var all=MartialPhoenix.Snapshot();var casts=all.Flights.Where(x=>x.Owner==p.Serial.Value).Select(x=>x.Cast).ToHashSet();MartialPhoenix.Restore(all with{Drops=all.Drops.Where(x=>x.Owner!=p.Serial.Value).ToArray(),Flights=all.Flights.Where(x=>x.Owner!=p.Serial.Value).ToArray(),Leases=all.Leases.Where(x=>!casts.Contains(x.Cast)).ToArray()});var fire=FireGround.Snapshot();FireGround.Restore(fire with{Patches=fire.Patches.Where(x=>x.Owner!=p.Serial.Value || x.Ability!=CombatAbility.PhoenixStrike).ToArray()});}
    private static void Swing(PlayerMobile p,Mobile t,CombatAbility ability=CombatAbility.PhoenixStrike){Ready(p);Require(ClassCombat.Perform(p,ability,t,t.Location,Core.TickCount),"Begin "+ability);ClassCombat.ReleaseCast(p);long at=ClassCombat.For(p).EffectAt;Require(!ClassCombat.ResolveAction(p,at-1) && ClassCombat.ResolveAction(p,at) && !ClassCombat.ResolveAction(p,at),"One action event");}
    private static void Differential()
    {
        using var doc=JsonDocument.Parse(File.ReadAllText(Path.Join(Core.BaseDirectory,"phoenix-builder-source-probe.json")));int count=0;
        foreach(var r in doc.RootElement.EnumerateArray()){int V(int i)=>r[i].GetInt32();bool old=V(0)>0,valid=V(5)!=0 && V(6)!=0,gain=valid && V(3)!=0 && (old || V(4)!=0);if(gain){var previous=old?new MartialCharge(1,CombatAbility.PhoenixStrike,V(0),V(1),V(0)*25,DateTime.UnixEpoch.AddMilliseconds(321*40)):null;var state=AssassinCharges.Build(previous,1,Values(V(2)),DateTime.UnixEpoch.AddMilliseconds(100*40));Require(state.Count==V(9) && state.AttackPercent==V(10) && state.InitialRank==V(11) && state.UntilUtc==DateTime.UnixEpoch.AddMilliseconds(V(12)*40),"Complete source do34 builder");}count++;}
        Require(count==512,"Builder source matrix");for(int rank=1;rank<=255;rank++){var v=Values(rank);Require(v.Mana256==1024 && v.Formula("toht")==25+10*(rank-1) && v.Eval("aurastatcalc2")==25 && v.Eval("auralencalc")==375,"Current Phoenix rank/payment/AR");}
    }
    private static void Lifecycle()
    {
        var p=Fresh();var t=Target(p);Swing(p,t);var charge=State(p);
        for(int cause=0;cause<3;cause++)
        {
            p.Mana=p.ManaMax;Ready(p);int mana=NecromancerEffects.ManaBalance256(p);Require(ClassCombat.Perform(p,CombatAbility.PhoenixStrike,t,t.Location,Core.TickCount),"Lifecycle paid start");long at=ClassCombat.For(p).EffectAt;
            if(cause==0){Require(HitRecovery.Apply(p,p.HitsMax,Core.TickCount),"FHR");}
            if(cause==1){p.Direction=Direction.West;Require(p.Move(Direction.West),"Outward move");p.Direction=Direction.East;Require(p.Move(Direction.East),"Return move");}
            if(cause==2){var weapon=CombatTiming.Equipped(p);p.AddToBackpack(weapon);ClassGear.Refresh(p);Require(p.EquipItem(weapon),"Re-equip");ClassGear.Refresh(p);}
            Require(ClassCombat.For(p).TigerAttack==null && !ClassCombat.ResolveAction(p,at) && State(p)==charge && NecromancerEffects.ManaBalance256(p)==mana-1024,"Paid lifecycle replay/refund/charge loss "+cause);
        }
        Ready(p);ClearRelease(p);var history=Fresh();history.AddToBackpack(CombatTiming.Equipped(history));AssassinCharges.Gain(history,SkillMechanics.Values(history,CombatAbility.PhoenixStrike));Require(ClassCreation.Profiles.TryActivateHistory(history,DiabloClass.Paladin) && !AssassinCharges.Any(history) && ClassCreation.Profiles.TryActivateHistory(history,DiabloClass.Assassin),"Idle history retained charge");history.Delete();
        AssassinCharges.Gain(p,SkillMechanics.Values(p,CombatAbility.PhoenixStrike));p.Kill();p.Resurrect();Require(State(p)==null,"Death retained charge");p.Corpse?.Delete();AssassinCharges.Gain(p,SkillMechanics.Values(p,CombatAbility.PhoenixStrike));ClassCreation.Profiles.TryGet(p.Serial,out var profile);ClassCreation.Profiles.ResetAllocatedPoints(p,profile);Require(State(p)==null && ClassCombat.For(p).TigerAttack==null,"Respec retained charge/action");t.Delete();p.Delete();
    }
    private static void Check()
    {
        Differential();Lifecycle();var p=Fresh();var t=Target(p);Require(SkillBindings.Instance.Assign(p,true,CombatAbility.PhoenixStrike) && SkillBindings.Instance.Assign(p,false,CombatAbility.PhoenixStrike) && SkillBindings.Instance.AssignQuick(p,0,CombatAbility.PhoenixStrike),"Phoenix bindings");NecromancerEffects.SetMana256(p,20*256+17);int mana=NecromancerEffects.ManaBalance256(p),hp=SkillHealth.Balance256(t);Ready(p);Require(ClassCombat.Perform(p,CombatAbility.PhoenixStrike,t,t.Location,Core.TickCount),"Paid start");var action=ClassCombat.For(p);Require(State(p)==null && SkillHealth.Balance256(t)==hp && NecromancerEffects.ManaBalance256(p)==mana-1024,"Start paid but hit/charged early");ClassCombat.ReleaseCast(p);Require(ClassCombat.ResolveAction(p,action.EffectAt) && State(p) is{Count:1,AttackPercent:25} && MartialPhoenix.Snapshot().Flights.All(x=>x.Owner!=p.Serial.Value) && MartialPhoenix.Snapshot().Drops.All(x=>x.Owner!=p.Serial.Value),"Charging released a progressive tier");
        Swing(p,t);Swing(p,t);Require(State(p) is{Count:3,AttackPercent:75},"Three independent charges");var held=State(p);TigerStrikes.HitRoll=()=>1;Swing(p,t);Require(State(p)==held,"Miss gained/refreshed");Swing(p,t,CombatAbility.BasicAttack);Require(State(p)==held,"Missed finisher consumed");TigerStrikes.HitRoll=()=>0;
        t.SetResistance(ResistanceType.Physical,100);AssassinCharges.Clear(p);p.Mana=p.ManaMax;Swing(p,t);Require(State(p)?.Count==1,"Immune contact failed to charge");t.SetResistance(ResistanceType.Physical,0);AssassinCharges.Gain(p,SkillMechanics.Values(p,CombatAbility.TigerStrike));AssassinCharges.Gain(p,SkillMechanics.Values(p,CombatAbility.CobraStrike));AssassinCharges.Gain(p,SkillMechanics.Values(p,CombatAbility.FistsOfFire));AssassinCharges.Gain(p,SkillMechanics.Values(p,CombatAbility.ClawsOfThunder));AssassinCharges.Gain(p,SkillMechanics.Values(p,CombatAbility.BladesOfIce));Swing(p,t);Require(AssassinCharges.Finisher(p).Length==6 && State(p)?.Count==2 && AssassinCharges.State(p)?.Count==1,"Six families/builder consumption");AssassinCharges.Clear(p);
        Swing(p,t);Swing(p,t);Swing(p,t);NecromancerEffects.SetMana256(p,1023);Swing(p,t);Require(State(p)?.Count==2 && NecromancerEffects.ManaBalance256(p)==1023 && MartialPhoenix.Snapshot().Flights.Count(x=>x.Owner==p.Serial.Value && x.Cold)==16,"Low mana ordinary charged fallback");ClearRelease(p);p.Mana=p.ManaMax;
        var helm=NamedGear.Create(NamedGear.Catalog.Items.Single(x=>x.SourceKey=="Tarnhelm").Id,99,new Maximum(),true);p.AddToBackpack(helm);Require(p.EquipItem(helm),"Actual soft rank");ClassGear.Refresh(p);AssassinCharges.Clear(p);Swing(p,t);Require(State(p)?.InitialRank==SkillMechanics.Rank(p,CombatAbility.PhoenixStrike),"Actual current rank capture");p.AddToBackpack(helm);ClassGear.Refresh(p);Require(State(p).InitialRank>SkillMechanics.Rank(p,CombatAbility.PhoenixStrike),"Retained initial rank");
        Ready(p);mana=NecromancerEffects.ManaBalance256(p);Require(ClassCombat.Perform(p,CombatAbility.PhoenixStrike,t,t.Location,Core.TickCount),"Cancel start");long eventAt=ClassCombat.For(p).EffectAt;ClassCombat.Stop(p);Require(!ClassCombat.ResolveAction(p,eventAt) && NecromancerEffects.ManaBalance256(p)==mana-1024,"Cancel replay/refund");
        Hold(p,State(p) with{UntilUtc=TimedEffects.Now.AddHours(1)});var pending=Fresh();var other=Target(pending);Ready(pending);Require(ClassCombat.Perform(pending,CombatAbility.PhoenixStrike,other,other.Location,Core.TickCount),"Pending save start");ClassCombat.For(pending).EffectAt=Core.TickCount+3600000;ClassCombat.For(pending).NextAction=Core.TickCount+3601000;
        File.WriteAllText(Manifest,JsonSerializer.Serialize(new Saved(p.Serial.Value,t.Serial.Value,State(p),NecromancerEffects.ManaBalance256(p),pending.Serial.Value,NecromancerEffects.ManaBalance256(pending),p.Location)));Log.Information("Phoenix builder:512 complete source contexts/255 rank controls,once-paid4mana,single A1 event,independent6families,miss/immunity/low-mana charged fallback,actual item/stored rank and cancellation pass");
    }
    private static void Reload(){Differential();var s=JsonSerializer.Deserialize<Saved>(File.ReadAllText(Manifest));var p=(PlayerMobile)World.FindMobile((Serial)s.Owner);var pending=(PlayerMobile)World.FindMobile((Serial)s.Pending);Require(State(p)==s.State && NecromancerEffects.ManaBalance256(p)==s.Mana256 && State(pending)==null && ClassCombat.For(pending).PendingAbility==CombatAbility.None && ClassCombat.For(pending).TigerAttack==null && NecromancerEffects.ManaBalance256(pending)==s.PendingMana,"Saved charges/paid windup/no replay or refund");p.MoveToWorld(s.Origin,Map.Trammel);}
    private static void Input()
    {
        var p=Fresh();var t=Target(p);Require(SkillBindings.Instance.Assign(p,true,CombatAbility.PhoenixStrike) && SkillBindings.Instance.Assign(p,false,CombatAbility.PhoenixStrike) && SkillBindings.Instance.AssignQuick(p,0,CombatAbility.PhoenixStrike),"Input bindings");Ready(p);var net=NetState.Instances.Single(x=>x.Mobile==null && IPAddress.IsLoopback(x.Address));net.Seeded=true;net.SentFirstPacket=true;net.CompressionEnabled=false;net.Mobile=p;p.NetState=net;var field=typeof(NetState).GetField("_protocolState",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic);field.SetValue(net,Enum.Parse(field.FieldType,"GameServer_LoggedIn"));net.ResetMovementState();net.SendMobileUpdate(p);
        var hit=TigerStrikes.HitRoll;var elem=TigerStrikes.ElementRoll;var phys=TigerStrikes.PhysicalRoll;var effects=TigerStrikes.Effects;TigerStrikes.HitRoll=()=>0;TigerStrikes.ElementRoll=()=>0;TigerStrikes.PhysicalRoll=_=>0;TigerStrikes.Effects=new Maximum();int phase=0,mana=NecromancerEffects.ManaBalance256(p),life=SkillHealth.Balance256(t);uint sequence=0;bool stopping=false;long deadline=Core.TickCount+15000;
        void Cleanup(){ClearRelease(p);TigerStrikes.HitRoll=hit;TigerStrikes.ElementRoll=elem;TigerStrikes.PhysicalRoll=phys;TigerStrikes.Effects=effects;t.Delete();p.Delete();}
        void Announce()=>Log.Information("phoenix-builder-input: ready action={Action} ability={Ability} target={Target} x={X} y={Y} z={Z}",phase is 0 or 3?3:phase==1?4:7,(int)(phase==3?CombatAbility.BasicAttack:CombatAbility.PhoenixStrike),t.Serial.Value,t.X,t.Y,t.Z);
        void Wait(){try{Require(Core.TickCount<deadline && net.Running && p.NetState==net,"Live Phoenix input timeout/disconnection");if(phase==3 && State(p)==null && Core.TickCount>=ClassCombat.For(p).NextAction){Require(NecromancerEffects.ManaBalance256(p)==mana && SkillHealth.Balance256(t)<life && MartialPhoenix.Snapshot().Drops.Any(x=>x.Owner==p.Serial.Value),"Ordinary charged finisher/nonstacked meteor");Cleanup();Log.Information("phoenix-builder-input-result: passed");return;}if(phase<3 && State(p)?.Count==1 && !stopping){stopping=true;sequence=ClassCombat.For(p).Sequence;Log.Information("phoenix-builder-input-stop: phase={Phase}",phase);}if(phase<3 && stopping && ClassCombat.For(p).Sequence>sequence && ClassCombat.For(p).HeldAbility==CombatAbility.None && State(p)?.Count==1 && ClassCombat.For(p).TigerAttack==null && Core.TickCount>=ClassCombat.For(p).NextAction){Require(NecromancerEffects.ManaBalance256(p)==mana-1024 && SkillHealth.Balance256(t)<life,"Natural one paid source contact");phase++;stopping=false;if(phase<3){AssassinCharges.Clear(p);}Ready(p);mana=NecromancerEffects.ManaBalance256(p);life=SkillHealth.Balance256(t);Announce();}Timer.StartTimer(TimeSpan.FromMilliseconds(10),Wait);}catch(Exception e){Cleanup();Log.Error(e,"phoenix-builder-input-result: failed");}}
        Timer.StartTimer(TimeSpan.FromMilliseconds(30),()=>{Announce();Wait();});
    }
}
